mapper.select:
SELECT * FROM approval_record
WHERE approval_time BETWEEN #{startDate} AND #{endDate}
ORDER BY approval_time DESC

SELECT * FROM approval_record
WHERE receipt_id = #{receiptId}
  AND approver_id = #{approverId}
ORDER BY approval_time DESC

SELECT * FROM approval_record
WHERE receipt_id = #{receiptId}
  AND approval_level = #{approvalLevel}
LIMIT 1
